import numpy as np

def calc_bias_variance(y_true_scalar: float, preds_array: np.ndarray) -> dict:
    mean_pred = float(np.mean(preds_array))
    bias2 = float((mean_pred - y_true_scalar) ** 2)
    var = float(np.mean((preds_array - mean_pred) ** 2))
    return {"bias_squared": round(bias2, 4), "variance": round(var, 4)}

calc_bias_variance(2.0, np.array([1.5, 2.5, 2.0, 1.0, 3.0]))

