import numpy as np

def soft_threshold(z, lam: float):
    z_arr = np.asarray(z, dtype=float)
    return np.sign(z_arr) * np.maximum(np.abs(z_arr) - lam, 0.0)

list(np.round(soft_threshold(np.array([-2.5, -0.5, 0.2, 0.8, 3.0]), 0.6), 4))
